(() => {
  'use strict';
  const $=id=>document.getElementById(id);let ctx,commands=[],selectedAction=null,jobTimer=null,archived=false;
  function tell(text){ctx.toast(text);}
  async function busy(button,work){if(button.disabled)return;button.disabled=true;button.dataset.pending='true';button.setAttribute('aria-busy','true');try{const result=await work();button.dataset.feedback='success';return result;}catch(e){button.dataset.feedback='error';tell(e.message);return undefined;}finally{button.disabled=false;delete button.dataset.pending;button.removeAttribute('aria-busy');setTimeout(()=>delete button.dataset.feedback,1300);}}
  async function refresh(){await ctx.reload();}
  async function manage(){if(!ctx.current()){tell('请先选择微信聊天');return;}await busy($('manage-chat'),async()=>{const result=await ctx.data('thread/'+ctx.current());$('archive-confirm').checked=false;$('discard-confirm').checked=false;$('manage-title').textContent=result.thread.title;$('manage-name').value=result.thread.title;$('manage-cwd').textContent=result.thread.cwd||'尚未绑定线程；首次发送时继承主会话目录';$('manage-draft').textContent=result.thread.pendingText||'没有微信文字草稿';$('manage-files').textContent=(result.thread.pendingFiles||[]).map(f=>'📎 '+f.name).join('\n')||'没有微信附件草稿';$('manage-dialog').showModal();});}
  async function archiveList(){archived=!archived;$('archived-list').hidden=!archived;if(!archived)return;await busy($('view-archived'),async()=>{const list=await ctx.data('archived');$('archived-list').replaceChildren();if(!list.length)$('archived-list').textContent='暂无归档聊天';for(const chat of list){const row=document.createElement('div');row.className='archived-entry';const label=document.createElement('span');label.textContent=chat.title;const button=document.createElement('button');button.textContent='恢复';button.onclick=()=>busy(button,async()=>{await ctx.data('thread/'+chat.threadId+'/restore',{});row.remove();await refresh();tell('聊天已恢复，历史和绑定保留');});row.append(label,button);$('archived-list').append(row);}});}
  function listCommands(){const query=$('command-search').value.trim().toLowerCase(),group=$('command-group').value;$('command-list').replaceChildren();let count=0;for(const action of commands){if(group&&action.group!==group)continue;if(query&&!`${action.label} ${action.group} ${action.template}`.toLowerCase().includes(query))continue;const button=document.createElement('button');button.className='command-card';const title=document.createElement('strong');title.textContent=action.label;const sub=document.createElement('span');sub.textContent=action.group;button.append(title,sub);button.onclick=()=>openAction(action);$('command-list').append(button);count++;}$('command-count').textContent=count+' 项操作';}
  async function tools(){if(!ctx.current()){tell('请先选择聊天');return;}await busy($('tools-button'),async()=>{commands=await ctx.data('commands');$('command-group').replaceChildren();for(const group of ['',...new Set(commands.map(a=>a.group))]){const option=document.createElement('option');option.value=group;option.textContent=group||'全部功能';$('command-group').append(option);}$('command-search').value='';listCommands();$('tools-dialog').showModal();});}
  function openAction(action,prefill={}){if(action.id==='model-set'){if($('tools-dialog').open)$('tools-dialog').close();ctx.showModels();return;}selectedAction=action;clearTimeout(jobTimer);$('action-title').textContent=action.label;$('action-fields').replaceChildren();$('action-result').replaceChildren();$('action-choices').replaceChildren();$('action-state').textContent='操作所选微信聊天：'+$('title').textContent;$('action-confirm-wrap').hidden=!action.confirm;$('action-confirm').checked=false;$('action-confirm-text').textContent=action.confirm||'';$('action-command').textContent=action.template;$('action-delivery').textContent=action.delivery==='wechat'?'由原微信桥接执行，任务结果仍发送到微信。':'结果显示在本面板，使用原微信聊天的配置和上下文。';$('execute-action').textContent='执行操作';delete $('execute-action').dataset.requestId;for(const field of action.fields){const label=document.createElement('label');const caption=document.createElement('span');caption.textContent=field.label+(field.required?' *':'');const input=document.createElement(field.type==='select'?'select':field.type==='textarea'?'textarea':'input');input.name=field.key;input.required=!!field.required;input.dataset.field=field.key;input.maxLength=100000;if(field.type==='select')for(const value of field.options||[]){const option=document.createElement('option');option.value=value;option.textContent=({'default-permissions':'默认权限','auto-review':'自动审核','full-access':'完全访问','custom':'自定义','on':'开启','off':'关闭','friendly':'友好','pragmatic':'务实','none':'不设置风格','zh':'中文','en':'English'})[value]||value;input.append(option);}else input.placeholder=field.placeholder||'';if(field.type==='textarea')input.rows=4;if(prefill[field.key])input.value=prefill[field.key];label.append(caption,input);$('action-fields').append(label);}if(['allow-once','allow-session','deny'].includes(action.id)){$('execute-action').textContent='前往当前任务审批';}$('action-dialog').showModal();}
  function choicesView(choices){$('action-choices').replaceChildren();for(const choice of choices||[]){const box=document.createElement('section');box.className='choice-card';const title=document.createElement('strong');title.textContent=choice.title;const detail=document.createElement('p');detail.textContent=String(choice.description||'').slice(0,220);box.append(title,detail);const operations=choice.kind==='thread'?[['thread-peek','预览'],['thread-open','绑定到当前微信聊天'],['thread-del','归档'],['thread-pin','置顶']]:choice.kind==='skills'?[['skills-show','详情'],[choice.enabled?'skills-off':'skills-on',choice.enabled?'停用':'启用']]:choice.kind==='plugins'?[['plugins-show','详情'],[choice.installed?'plugins-del':'plugins-add',choice.installed?'卸载':'安装']]:choice.kind==='apps'?[['apps-show','详情'],[choice.enabled?'apps-off':'apps-on',choice.enabled?'停用':'启用'],['apps-auth','授权']]:[['mcp-auth','授权'],[choice.enabled?'mcp-off':'mcp-on',choice.enabled?'停用':'启用']];for(const [id,label] of operations){const action=commands.find(a=>a.id===id);if(!action)continue;const b=document.createElement('button');b.textContent=label;b.onclick=()=>openAction(action,{target:choice.target});box.append(b);}$('action-choices').append(box);}}
  async function watchJob(id){try{const job=await ctx.data('action/'+id);if($('execute-action').dataset.requestId!==id)return;$('action-state').textContent=job.state==='running'?'原微信桥接正在处理…':job.state==='failed'?'操作失败':'已收到原桥接结果';CWRender.render($('action-result'),job.error||job.text||'');choicesView(job.choices);if(job.state==='running'){jobTimer=setTimeout(()=>watchJob(id),1200);}else{const pending=JSON.parse(sessionStorage.getItem('cw-pending-action')||'null');if(pending?.requestId===id)sessionStorage.removeItem('cw-pending-action');await refresh();$('execute-action').textContent='再次执行';delete $('execute-action').dataset.requestId;}}catch(e){$('action-state').textContent='连接中断，操作结果待确认；请先查看微信或点击检查状态';tell(e.message);}}
  async function execute(){const action=selectedAction;if(!action)return;if(['allow-once','allow-session','deny'].includes(action.id)){$('action-dialog').close();$('tools-dialog').close();await ctx.showApproval(action.id==='allow-session');return;}await busy($('execute-action'),async()=>{const values={};$('action-fields').querySelectorAll('[data-field]').forEach(input=>{values[input.dataset.field]=input.value;});if(action.confirm&&!$('action-confirm').checked)throw new Error('请先勾选确认操作影响');const button=$('execute-action');const signature=JSON.stringify({id:ctx.current(),commandId:action.id,values});let stored;try{stored=JSON.parse(sessionStorage.getItem('cw-pending-action')||'null');}catch{}const requestId=stored?.signature===signature?stored.requestId:crypto.randomUUID();sessionStorage.setItem('cw-pending-action',JSON.stringify({signature,requestId}));button.dataset.requestId=requestId;const job=await ctx.data('thread/'+ctx.current()+'/command',{commandId:action.id,values,confirmed:$('action-confirm').checked,requestId});$('action-state').textContent='操作已受理';watchJob(job.id);});}
  window.CWControls={init(context){ctx=context;$('manage-chat').onclick=()=>manage();$('tools-button').onclick=()=>tools();$('drawer-tools').onclick=()=>{$('drawer').hidden=true;$('drawer-shade').hidden=true;tools();};$('view-archived').onclick=archiveList;$('command-search').oninput=listCommands;$('command-group').onchange=listCommands;$('execute-action').onclick=execute;$('check-action').onclick=()=>{const id=$('execute-action').dataset.requestId;if(id)watchJob(id);else tell('尚无待检查的操作');};$('workspace-chat').onclick=()=>busy($('workspace-chat'),async()=>{if(!commands.length)commands=await ctx.data('commands');const action=commands.find(a=>a.id==='new-thread');if(action)openAction(action,{});});$('rename-chat').onclick=()=>busy($('rename-chat'),async()=>{const name=$('manage-name').value.trim();if(!name)throw new Error('请填写新名称');await ctx.data('thread/'+ctx.current()+'/rename',{name});await refresh();$('manage-title').textContent=name;tell('原微信聊天已改名');});$('archive-chat').onclick=()=>busy($('archive-chat'),async()=>{if(!$('archive-confirm').checked)throw new Error('请先确认归档，历史会保留');await ctx.data('thread/'+ctx.current()+'/archive',{});$('manage-dialog').close();await ctx.reselect();tell('聊天已归档');});$('discard-draft').onclick=()=>busy($('discard-draft'),async()=>{if(!$('discard-confirm').checked)throw new Error('请先确认清空草稿');await ctx.data('thread/'+ctx.current()+'/draft-discard',{confirmed:true});$('manage-draft').textContent='草稿已清空';$('manage-files').textContent='';await refresh();tell('已清空原微信草稿；手机输入框内容仍保留');});document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
    document.addEventListener('pointerdown',e=>{const b=e.target.closest('button');if(b&&!b.disabled){b.classList.add('pressed');setTimeout(()=>b.classList.remove('pressed'),170);if(typeof Native!=='undefined'&&Native.haptic)Native.haptic('feedback','tap');}},{passive:true});
  }};
})();
